def patterns(k):
    def single_pattern(n):
        if n == 1:
            return '1'
        return '0' + single_pattern(n - 1)

    def sequence(n):
        if n == 1:
            return '1'
        return sequence(n - 1) + '1' + single_pattern(n - 1)

    result = []
    for i in range(1, k + 1):
        pattern = sequence(i)
        result.append(pattern)
    return result

